  'useEverywhere.modalTitle': '隨處使用 Pixflow Design',
  'useEverywhere.modalSubtitle': '將 Pixflow Design 接入任何 IDE、Agent 或指令碼 — CLI、HTTP、MCP 及 Skills。使用「複製 Agent 指南」並貼到 Claude Code、Codex、Cursor、openclaw 或 hermes 中，即可設定一切。',
